import base64, gzip, re

def varrer(ult_nsu="000000000000000", limite_paginas=200):
    for _ in range(limite_paginas):
        xml = distribuir(ult_nsu)
        for b64 in re.findall(r"<docZip[^>]*>([^<]+)</docZip>", xml):
            yield gzip.decompress(base64.b64decode(b64)).decode("utf-8")
        ult = re.search(r"<ultNSU>(\d+)</ultNSU>", xml)
        mx = re.search(r"<maxNSU>(\d+)</maxNSU>", xml)
        if not ult or not mx:
            break
        ult_nsu = ult.group(1)
        if int(ult_nsu) >= int(mx.group(1)):
            break

